-- Row 1: ae6ddf4c-ecd3-4e84-8119-665b893811ae
INSERT INTO analyses (id, submission_id, enrichment_id, company_id, swot, pestel, porter, okrs, synthesis, tam_sam_som, benchmarking, blue_ocean, growth_hacking, scenarios, bsc, decision_matrix, status, error_message, processing_time_ms, is_visible_to_user, is_blurred, is_public, access_code, access_code_created_at, pdf_url, pdf_generated_at, approved_at, approved_by, sent_at, sent_to, created_at, updated_at, completed_at, deleted_at)
VALUES ('ae6ddf4c-ecd3-4e84-8119-665b893811ae', NULL, NULL, NULL, '{"summary": "Baldan é player tradicional pressionado por juros altos e rivalidade, mas pode criar oceano azul ao migrar de fabricante de máquinas para plataforma de serviços, dados e soluções sustentáveis.", "threats": [{"source": "fato", "content": "Juros SELIC de 14,90% reduzem capacidade de financiamento de máquinas agrícolas", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Concorrentes globais avançam em máquinas conectadas e plataformas proprietárias", "confidence": "Média"}, {"source": "fato", "content": "Câmbio a R$ 5,36 pressiona custos de componentes importados e margens da Baldan", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Endurecimento de normas ambientais pode exigir investimentos rápidos e pesados", "confidence": "Média"}], "strengths": [{"source": "análise de mercado", "content": "Usar marca quase centenária para acelerar adoção de novos serviços digitais", "confidence": "Média"}, {"source": "análise de mercado", "content": "Expandir portfólio físico para soluções híbridas máquina+dados no campo", "confidence": "Média"}, {"source": "análise de mercado", "content": "Aproveitar maturidade digital média-alta para pilotar ofertas de IA agrícola", "confidence": "Média"}, {"source": "estimativa", "content": "Usar base atual de clientes e revendas para escalar novos serviços recorrentes", "confidence": "Baixa"}], "weaknesses": [{"source": "análise de mercado", "content": "Modelo focado em venda de máquinas, com baixa receita recorrente em serviços", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Capacitação limitada em IA e analytics aplicada ao agronegócio do cliente", "confidence": "Média"}, {"source": "análise de mercado", "content": "Baixa diferenciação percebida frente a grandes players globais em tecnologia", "confidence": "Média"}, {"source": "análise de mercado", "content": "Dependência de crédito rural encarece vendas com SELIC em 14,90% a.a.", "confidence": "Alta"}], "opportunities": [{"source": "análise de mercado", "content": "Criar plataforma de serviços e dados agrícolas como novo centro de lucro recorrente", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Desenvolver soluções sustentáveis ligadas a solo e insumos com métricas de ESG", "confidence": "Média"}, {"source": "análise de mercado", "content": "Oferecer assinaturas de manutenção, telemetria e suporte agronômico remoto", "confidence": "Média"}, {"source": "análise de mercado", "content": "Formar ecossistema com agtechs e cooperativas para acelerar inovação em campo", "confidence": "Média"}]}'::jsonb, '{"legal": ["Evolução do Plano Safra atrelada à SELIC 14.90% pode redesenhar regras de crédito para máquinas.", "Com PIB 2.20 %, ajustes tributários no agro podem afetar margens de revendas e distribuidores.", "Maior exigência legal de rastreio ambiental pode impulsionar soluções digitais embarcadas Baldan."], "social": ["Desemprego 5.60 % incentiva mecanização, exigindo da Baldan oferta de máquinas fáceis de operar.", "PIB per capita 47802.02 BRL limita adoção de alto ticket, abrindo espaço a pacotes modulares.", "Serviços 0.60 % indica espaço para contratos de serviço contínuo em vez de venda pontual."], "summary": "Cenário de SELIC 14.90% e câmbio R$ 5.36/USD pressiona o modelo atual. Há espaço de oceano azul em serviços, dados e soluções sustentáveis, alavancando a tradição da Baldan e sua maturidade digital.", "economic": ["SELIC 14.90% encarece crédito e incentiva modelos de uso de máquinas via serviço, não só venda.", "Câmbio R$ 5.36/USD favorece exportar implementos, mas encarece eletrônica e sensores importados.", "Inflação 0.09% (12 meses) e comércio -0.30 % sugerem produtor mais sensível a preço e payback."], "political": ["Dependência do Plano Safra com PIB 2.20 % limita espaço para políticas pró-inovação no agro.", "Indústria -0.40 % pressiona governo por incentivos, podendo favorecer gigantes globais do setor.", "Desemprego 5.60 % pode deslocar foco fiscal de subsídios ao agro para programas sociais urbanos."], "environmental": ["Normas ambientais em emissões pressionam por implementos que reduzam passadas e consumo no campo.", "IPP -0.25 % abre janela para testar materiais e aços mais verdes sem forte repasse imediato.", "Construção_cost 0.27 % reforça pauta de conservação de solo e nichos em soluções anti-erosão."], "technological": ["Indústria -0.40 % exige ganhos de produtividade; telemetria e precisão viram diferencial crítico.", "Com digitalização em alta, maturidade média-alta da Baldan permite testar plataformas data-driven.", "Câmbio R$ 5.36/USD pressiona a nacionalizar sensores e software, criando ecossistema local."]}'::jsonb, '{"summary": "O setor de máquinas e implementos agrícolas segue relevante e com crescimento projetado de 4-7% a.a., mas combina alta rivalidade e forte poder de compra em ambiente de juros de 14,90%. Para criar oceano azul, Baldan deve migrar de produto para plataforma, alavancar ecossistemas e capturar liderança em IA e dados no campo.", "buyer_power": "Poder de compradores é alto: SELIC 14,90% encarece crédito do Plano Safra, forçando descontos, barter e garantias; com inflação de 0,09% e desemprego em 5,60%, produtores resistem a reajustes, exigindo propostas de valor e ROI por hectare bem claros.", "supplier_power": "Poder de fornecedores é médio: câmbio a R$5,36 e SELIC 14,90% encarecem insumos importados, mas IPP -0,25% e indústria -0,40% indicam ociosidade, abrindo margem para Baldan negociar aço, componentes e fretes em contratos estruturados.", "disruption_ai_data": "IA e dados já mudam o agro: telemetria, recomendações agronômicas e manutenção preditiva deslocam valor da máquina para a plataforma; se Baldan não liderar soluções data-driven, pode ser comoditizada por players globais e agtechs até 2025+.", "threat_substitutes": "Ameaça de substitutos é média: agricultura de precisão, drones e serviços de plantio terceirizado podem reduzir vendas de implementos tradicionais; porém, preparo de solo segue crítico, abrindo espaço para Baldan ofertar pacotes máquina+serviço+dados.", "competitive_rivalry": "Alta rivalidade com John Deere, CNH, AGCO e outros em setor concentrado; indústria -0,40% pressiona preços, exigindo da Baldan diferenciação em serviços, dados agronômicos e canais digitais para capturar crescimento de 4-7% a.a.", "threat_new_entrants": "Ameaça de novos entrantes é baixa: barreiras de capital, engenharia, rede de revendas e pós-venda são altas; com indústria -0,40% e juros a 14,90%, poucos novos players suportam o ciclo longo de payback, protegendo Baldan, mas sem espaço para inércia.", "buyer_power_intensity": "Alta", "overall_attractiveness": "Média", "strategic_implications": ["Criar plataforma digital Baldan (telemetria, dados de solo, recomendações) integrada aos implementos para tirar foco de preço e migrar a disputa para valor agronômico e produtividade comprovada por dados.", "Desenhar ofertas Blue Ocean combinando máquina+serviço+dados (ex.: cobrança por hectare trabalhado, manutenção preditiva, treinamento remoto) focadas em produtores médios e cooperativas estratégicas.", "Estruturar ecossistema com agtechs, cooperativas, revendas e fintechs rurais para crédito integrado, barter e seguros, amortecendo impacto da SELIC de 14,90% na decisão de compra e reduzindo risco de inadimplência.", "Otimizar compras globais e parcerias industriais para mitigar câmbio a R$5,36 e capturar IPP -0,25%, assegurando custo competitivo em aço e componentes críticos e liberando margem para investir em inovação digital."], "supplier_power_intensity": "Média", "disruption_ai_data_intensity": "Alta", "threat_substitutes_intensity": "Média", "competitive_rivalry_intensity": "Alta", "power_partnerships_ecosystems": "Parcerias têm poder alto: conexões com agtechs de telemetria, cooperativas, revendas e fintechs rurais, ancoradas em PIB 12m de 3,20% e serviços a 0,60%, podem transformar Baldan em hub de soluções do agro, reduzindo dependência apenas da máquina.", "threat_new_entrants_intensity": "Baixa", "power_partnerships_ecosystems_intensity": "Alta"}'::jsonb, '{"summary": "Plano de 90 dias para estruturar célula de inteligência, desenhar MVP da Baldan Digital e preparar pilotos de serviços recorrentes com risco jurídico controlado.", "plan_90_days": [{"focus": "Fundação", "month": "Mês 1", "objective": "Estabelecer base organizacional, jurídica e analítica para Baldan Digital e serviços recorrentes", "investment": "R$ 10-20 mil", "key_results": ["Formar célula de inteligência com 4 pessoas nomeadas (Resp: Dir. Estratégia)", "Desenhar visão 12 meses da Baldan Digital em 1 documento (Resp: PMO Digital)", "Obter 1 parecer jurídico preliminar LGPD e contratos (Resp: Jurídico)"], "aligned_recommendation": "Criar célula de inteligência macroeconômica e competitiva para orientar o oceano azul"}, {"focus": "Crescimento", "month": "Mês 2", "objective": "Desenhar o MVP da plataforma Baldan Digital e o portfólio inicial de serviços recorrentes", "investment": "R$ 20-40 mil", "key_results": ["Definir backlog MVP com 20 épicos priorizados (Resp: Prod. Owner Digital)", "Selecionar 2 parceiros core de tech/IA e 1 de dados (Resp: TI)", "Modelar 2 pacotes de serviços recorrentes com preços (Resp: Pós-venda)"], "aligned_recommendation": "Lançar plataforma Baldan Digital (dados, telemetria e serviços recorrentes)"}, {"focus": "Consolidação", "month": "Mês 3", "objective": "Preparar pilotos integrados de Baldan Digital com serviços de manutenção e consultoria recorrentes", "investment": "R$ 30-50 mil", "key_results": ["Escolher 3 clientes âncora para pilotos integrados (Resp: Comercial)", "Treinar 12 pessoas da rede em oferta digital/serviços (Resp: RH)", "Aprovar roadmap e orçamento 12 meses no board (1 ciclo) (Resp: CFO)"], "aligned_recommendation": "Escalar serviços recorrentes de manutenção, retrofit e consultoria operacional"}], "success_metrics": ["Visão e roadmap 12 meses da Baldan Digital aprovados pela diretoria", "Portfólio inicial de 2-3 serviços recorrentes desenhado e precificado", "Pilotos planejados com 3 clientes âncora e orçamento validado para 12 meses"], "execution_phases": {"scale": {"focus": "Expansão controlada", "duration": "Meses 7-12", "objectives": ["Escalar a plataforma Baldan Digital para base ampliada de clientes foco", "Transformar serviços recorrentes em pilar relevante da nova receita"], "key_results": ["Alcançar 80 clientes ativos na Baldan Digital até o mês 12 (Resp: Diretor Comercial)", "Assinar 30 contratos anuais de serviços avançados até mês 12 (Resp: Pós-venda)"], "prerequisites": ["Validação bem-sucedida dos pilotos com NPS ≥ 8,0", "Métricas de uso ativo e resultado por hectare atingidas nas fazendas piloto"], "investment_range": "R$ 3-5 milhões"}, "foundation": {"focus": "Estruturação", "duration": "Meses 1-3", "objectives": ["Criar base organizacional, jurídica e analítica para a estratégia de oceano azul", "Desenhar visão e roadmap de 12 meses para Baldan Digital e serviços recorrentes"], "key_results": ["Célula de inteligência ativa com budget anual definido (Resp: Dir. Estratégia)", "Governança LGPD/dados e cronograma 12 meses com 30% buffer aprovados (Resp: Jurídico)"], "investment_range": "R$ 500-900 mil", "capacity_requirements": {"team": "6-10 pessoas núcleo dedicadas", "dependencies": ["Parecer jurídico LGPD e contratos de software/serviços", "Definição de parceiros de tecnologia, telemetria e dados de campo"], "skills_needed": ["Produto digital", "Dados e analytics", "Agronomia de precisão", "Jurídico LGPD e contratos", "Gestão de projetos e mudança"]}}, "validation": {"focus": "Pilotos", "duration": "Meses 4-6", "objectives": ["Rodar pilotos controlados do MVP da Baldan Digital com clientes selecionados", "Validar apetite e viabilidade de serviços recorrentes de manutenção e consultoria"], "key_results": ["Executar 1-3 pilotos Baldan Digital em até 10 máquinas clientes (Resp: PMO Digital)", "Fechar 5-10 contratos piloto de serviços recorrentes (Resp: Comercial/Pós-venda)"], "prerequisites": ["Fase 1 concluída com célula de inteligência instalada", "Aprovações de orçamento, LGPD e modelos contratuais obtidas"], "investment_range": "R$ 1,5-2,5 milhões"}}, "total_investment": "R$ 60-110 mil", "capacity_assessment": {"blockers": ["Resistência interna à migração de venda de máquina para modelo recorrente", "Dependência de parceiros de tecnologia para telemetria, IA e integrações no campo"], "team_readiness": "Média", "budget_adequacy": "Suficiente", "stakeholder_alignment": "Parcial"}}'::jsonb, '{"roadmap": ["Curto Prazo (3-6 meses): Criar célula de inteligência, desenvolver MVP da plataforma AgroData e iniciar 3 pilotos com cooperativas parceiras.", "Médio Prazo (6-12 meses): Validar modelo de assinatura, escalar para 15-20 cooperativas e integrar telemetria embarcada ao ecossistema digital.", "Longo Prazo (12+ meses): Consolidar posição como plataforma de referência em dados agrícolas, expandir para serviços financeiros e sustentabilidade."], "key_findings": ["Oceano azul está em serviços e dados, não em mais ferro: monetizar inteligência de uso real diferencia da guerra de preços.", "Cooperativas são canal ideal para pilotos: menor risco, maior volume e feedback qualificado para iteração rápida.", "Integração ao stack digital do produtor cria lock-in e eleva LTV, transformando cliente em assinante recorrente."], "main_findings": ["FORÇA: Marca centenária consolidada com portfólio robusto e maturidade digital média-alta, base sólida para pivô estratégico.", "FRAQUEZA: Dependência de crédito agrícola (Plano Safra) e modelo centrado em venda de máquinas, vulnerável a ciclos de juros.", "OPORTUNIDADE: Espaço inexplorado em serviços de dados, IA aplicada e soluções sustentáveis no agro brasileiro.", "AMEAÇA: Concorrentes globais (John Deere, Case IH) avançam em digitalização; SELIC 14.90% comprime margens e demanda."], "important_notes": ["SELIC 14.90% exige modelo de receita recorrente para reduzir dependência de financiamento de máquinas.", "Pilotos devem ter escopo jurídico controlado para mitigar riscos de SLA de performance por hectare.", "Validar capacidade interna de dados/IA antes de escalar; considerar parceria estratégica se gap crítico."], "central_challenge": "Migrar de fabricante tradicional de implementos agrícolas para orquestradora de ecossistema digital, criando receitas recorrentes em ambiente de juros altos (14.90%) e alta rivalidade competitiva.", "executive_summary": "Baldan, com 97 anos de tradição, enfrenta pressão de juros elevados e commoditização. A estratégia de oceano azul propõe transformação de vendedora de ferro para plataforma AgroData com serviços recorrentes, monetizando dados e garantindo performance por hectare. Pilotos com cooperativas validarão o modelo em 90 dias, preparando expansão de LTV e diferenciação sustentável.", "strategic_priorities": ["Estruturar célula de inteligência de dados e IA em 90 dias.", "Lançar MVP Baldan Digital com 3 cooperativas-piloto até Q2.", "Desenhar modelo de assinatura com SLA de performance validado juridicamente."], "consistency_validation": {"flags": ["Capacidade interna de IA/dados não confirmada; pode exigir contratação ou parceria.", "SLA de performance por hectare requer validação jurídica rigorosa antes de escalar."], "legal_alignment": true, "capacity_alignment": true, "financial_alignment": true, "overall_realism_score": 7}, "overall_recommendation": "Executar pivô controlado de fabricante para plataforma em 90 dias, validando com pilotos antes de escalar. Priorizar receita recorrente sobre volume de vendas."}'::jsonb, '{"sam": "R$ 7B - 13B", "som": "R$ 700M - 1.3B", "tam": "R$ 12B - 18B", "cagr": "+6% a.a. (baseado em: growth_rate setor 4-7% e tendências de precisão)", "summary": "Mercado brasileiro de máquinas e implementos agrícolas ~R$12-18B, com espaço para Baldan atingir SOM realista de R$700M-1.3B e crescer a ~6% a.a.", "assumptions": ["Receita Baldan R$500M-1B ≈5-10% do mercado de implementos (discovered_data + setor).", "Agronegócio BR TAM~R$1.2T; 1-2% alocado a máquinas/implementos (benchmark).", "Foco em médios/grandes produtores no Brasil ⇒ SAM=60-70% do TAM (perfil-alvo)."], "som_scenarios": {"realistic": {"probability": 50, "value_range": "R$ 700M - 1.3B", "market_share": "10%"}, "optimistic": {"probability": 20, "value_range": "R$ 1.3B - 2.3B", "market_share": "18%"}, "conservative": {"probability": 30, "value_range": "R$ 350M - 650M", "market_share": "5%"}}, "tam_scenarios": {"realistic": {"probability": 50, "value_range": "R$ 12B - 18B"}, "optimistic": {"probability": 20, "value_range": "R$ 16B - 22B"}, "conservative": {"probability": 30, "value_range": "R$ 10B - 14B"}}, "confidence_level": 65, "calculation_notes": "TAM estimado via receita Baldan como 5-10% do mercado; SAM 60-70% do TAM pelo foco em médios/grandes produtores.", "data_sources_used": {"direct_data": ["Receita anual Baldan estimada R$500M-1B (ENRICHMENT_DATA.discovered_data)"], "proxy_calculations": ["TAM calculado assumindo Baldan com 5-10% de market share em implementos.", "SOM calculado como % do SAM (5%, 10%, 18%) conforme cenários."], "benchmark_extrapolations": ["TAM agronegócio Brasil ~R$1.2T; 1-2% atribuído a máquinas/implementos."]}, "estimation_method": "proxy_concorrentes", "baseline_recommendation": "conservative"}'::jsonb, '{"summary": "Baldan é player tradicional em implementos agrícolas, competitivo em marca e portfólio, mas atrás de Stara, Jacto e multinacionais em conectividade, uso de dados e presença internacional. O mercado brasileiro de máquinas e implementos agrícolas é ~R$12-18B, com espaço para Baldan atingir SOM realista de R$700M-1,3B e crescer cerca de 6% a.a. ao buscar uma estratégia de oceano azul em serviços digitais, modelos recorrentes e soluções sustentáveis.", "best_practices": ["Marca tradicional e confiável em preparo de solo e plantio, reconhecida no mercado nacional.", "Portfólio amplo de implementos cobrindo várias culturas e etapas do ciclo agrícola.", "Boa capilaridade com revendas e presença forte em feiras, apoiando vendas e relacionamento."], "performance_gaps": ["Menor oferta de máquinas conectadas/telemetria que líderes em agricultura de precisão.", "Baixa presença internacional frente a multinacionais com forte rede global de vendas.", "Menor uso de dados/serviços digitais recorrentes vs. modelos de ''farming as a service''."], "competitors_analyzed": ["Stara", "Jacto", "Massey Ferguson (AGCO)", "John Deere", "Case IH (CNH Industrial)"]}'::jsonb, '{"raise": ["Uso de dados em tempo real para recomendação agronômica", "Garantia de performance por hectare em contrato", "Integração nativa com ERPs e plataformas do agro"], "create": ["Plataforma Baldan OS para gestão de operações de campo", "Modelos de assinatura vinculados a hectare trabalhado", "Marketplace de apps e serviços conectados aos implementos"], "reduce": ["Customizações mecânicas sob medida de baixo valor", "Complexidade de portfólio de implementos similares", "Dependência de feiras como principal canal de venda"], "summary": "Baldan migra de fabricante de implementos para orquestradora de um ecossistema digital de alta inteligência no campo. A empresa usa IA e dados de uso real para garantir performance por hectare, monetiza via assinaturas e serviços e se integra ao stack digital do produtor, reduzindo a relevância da disputa puramente por preço de máquina.", "eliminate": ["Venda isolada de máquinas sem serviços digitais", "Dependência de descontos comerciais para competir", "Desenvolvimento de produto desconectado dos dados de uso"], "new_value_curve": "Da venda de ferro ao ecossistema Baldan OS, com IA, dados e modelo por hectare."}'::jsonb, '{"summary": "Baldan cria oceano azul com plataforma AgroData e serviços recorrentes, usando pilotos com cooperativas para tração e expansão de LTV.", "leap_loop": {"name": "LEAP Loop", "type": "acquisition", "steps": ["Land: Atrair produtores via pilotos grátis da plataforma Baldan AgroData com cooperativas e revendas parceiras", "Engage: Engajar com diagnóstico digital de solo e máquinas, simulando ROI e ganhos ESG personalizados por safra", "Activate: Converter em assinantes vinculando compra/financiamento de máquinas a pacotes iniciais de dados e serviços", "Propagate: Incentivar indicações entre produtores e cooperativas com bônus em horas de consultoria e módulos AgroData"], "metrics": ["CAC por segmento (produtor, cooperativa, revenda)", "Custo por lead das campanhas AgroData", "Taxa de lead qualificado para piloto ativo", "Taxa de piloto para assinatura paga", "Leads originados por parceiros (revendas/coops)", "Coeficiente viral (indicações por cliente ativo)"], "bottleneck": "Baixa diferenciação percebida em tecnologia e dados dificulta provar valor da nova plataforma e travar a ativação"}, "scale_loop": {"name": "SCALE Loop", "type": "monetization", "steps": ["Satisfy: Entregar ganhos mensuráveis de produtividade, insumos e ESG via AgroData + manutenção e suporte agronômico remoto", "Convert: Vender planos de assinatura de telemetria, manutenção e agronomia vinculados à frota Baldan já instalada", "Loop Back: Renovar recorrência com reviews trimestrais de resultados, metas de safra e ajustes de pacote em conjunto", "Expand: Elevar LTV com upsell de novos módulos de dados, retrofit sustentável, seguros e soluções de crédito parceiro"], "metrics": ["LTV médio por cliente Baldan", "MRR/ARR de serviços e dados (plataforma AgroData)", "Taxa de adesão à assinatura na base instalada", "Churn de serviços recorrentes", "Receita de expansão por upsell/cross-sell", "Margem bruta de serviços versus venda de máquinas"], "bottleneck": "Modelo e estrutura focados em venda pontual de máquinas, com pouca capacidade em IA/analytics para escalar serviços recorrentes"}}'::jsonb, '{"realist": {"name": "Cenário Realista", "description": "SELIC em 14.90% a.a., câmbio R$ 5.36/USD e indústria em -0.40% mantêm crédito caro e investimento seletivo. PIB 2.20% e comércio -0.30% indicam cautela. Baldan sustenta vendas de implementos, mas margens apertam. Oceano azul surge em serviços, retrofit, dados e performance por hectare.", "probability": 60, "required_actions": ["Rebalancear mix para máquinas com melhor relação custo-benefício e pacotes de serviços acoplados", "Implantar pilotos de soluções data-driven em frotas Baldan, com cobrança recorrente por área monitorada", "Oferecer programas de retrofit e recondicionamento sustentável para base instalada", "Firmar parcerias financeiras para mitigar impacto da SELIC 14.90% a.a. no cliente final"]}, "summary": "O ambiente de juros altos (14.90% a.a.) e câmbio em R$ 5.36/USD pressiona o modelo centrado em ferro, mas abre espaço para um oceano azul em serviços, dados e soluções sustentáveis. Preparar-se exige criar receitas recorrentes, modular risco financeiro e ler cedo sinais macro e competitivos.", "optimistic": {"name": "Cenário Otimista", "description": "O agronegócio reage bem: PIB 3.20% 12m e serviços em 0.60% sustentam demanda. Mesmo com SELIC em 14.90% a.a. e câmbio em R$ 5.36/USD, produtores buscam produtividade, dados e sustentabilidade. Baldan cria oceano azul em serviços digitais, analytics de frota e soluções de carbono.", "probability": 20, "required_actions": ["Lançar portfólio de serviços digitais e contratos de manutenção preditiva com foco em produtividade", "Criar unidade de negócios de dados agrícolas e telemetria para produtores e cooperativas", "Desenvolver linha de soluções sustentáveis (carbono, solo, energia) com modelo de assinatura"]}, "pessimistic": {"name": "Cenário Pessimista", "description": "Persistem SELIC 14.90% a.a., indústria -0.40% e desemprego em 5.60%, com cortes em crédito rural. Câmbio em R$ 5.36/USD encarece componentes e reduz margem. Produtores adiam compras; Stara, Jacto e multinacionais avançam em plataformas proprietárias. Investimento em ferro cai; valor migra para serviço e dados.", "probability": 20, "required_actions": ["Focar geração de caixa, enxugar capex produtivo e priorizar projetos de rápida payback", "Migrar oferta para serviços de eficiência de uso do parque instalado e contratos de performance", "Rever portfólio, descontinuando linhas menos rentáveis e priorizando soluções leves e digitais"]}, "mitigation_tactics": ["Implementar gestão ativa de riscos financeiros com hedge parcial de câmbio R$ 5.36/USD e simulações de sensibilidade à SELIC 14.90% a.a.", "Aumentar participação de receitas recorrentes via serviços, dados e contratos de longo prazo com clientes-chave", "Tornar a estrutura de custos mais variável, usando manufatura enxuta e parcerias para picos de demanda", "Criar um escritório de futuro e inovação para monitorar cenários, concorrência e adaptar o roadmap de oceano azul"], "early_warning_signals": ["Mudanças bruscas na taxa de juros de 14.90% a.a. ou nas condições do crédito rural e Plano Safra", "Variação relevante na produção industrial (-0.40%), serviços (0.60%) e desemprego (5.60%) impactando confiança do produtor", "Movimentos de Stara, Jacto, John Deere e Case IH em plataformas digitais, telemetria e modelos de assinatura"]}'::jsonb, '{"summary": "Modelo ALIGN foca na migração para receitas recorrentes digitais, usando IA e dados de uso para entregar performance por hectare, integrando-se ao stack do produtor e elevando a proposta de valor além do preço da máquina.", "customer": ["Garantir performance contratada por hectare com dados em tempo real", "Aumentar NPS dos produtores que usam o ecossistema digital Baldan"], "financial": ["Elevar receita recorrente via assinaturas e serviços digitais", "Reduzir dependência de vendas de máquinas puras"], "learning_growth": ["Capacitar time comercial para venda consultiva de soluções de dados", "Atrair e reter talentos em IA, produto digital e ciência de dados"], "internal_processes": ["Criar plataforma de dados integrada ao stack digital do produtor", "Implementar telemetria em 80% da frota conectável até 3 anos"]}'::jsonb, '{"score": "8.1/10", "summary": "A matriz multicriterial (ROI em 5 anos, risco de execução e grau de diferenciação) indica que a Alternativa B – plataforma digital de dados, telemetria e serviços em modelo SaaS – oferece o melhor equilíbrio entre criação de oceano azul, escalabilidade e proteção em um contexto de juros de 14,90% a.a. e câmbio em R$ 5,36/USD, com score de 8,1/10, cerca de 18% acima da segunda melhor opção.\n\nA Alternativa A (serviços recorrentes de manutenção/retrofit/consultoria) apresenta bom potencial de ROI, mas menor diferenciação e maior dependência da estrutura atual de campo. A Alternativa C (soluções sustentáveis e pacotes verdes) é importante para posicionamento e acesso a crédito, porém mais dependente de mudanças regulatórias e de financiamento público.\n\nPróximos passos sugeridos:\n1) Em até 90 dias: detalhar o business case da Baldan Digital, definir arquitetura tecnológica, parceiros e governança de dados; acionar jurídico para contratos de software, LGPD e responsabilidade civil. 2) Em 6-9 meses: lançar MVP da plataforma para um segmento-piloto (clientes médios e grandes com maior propensão à digitalização), em conjunto com 2-3 pacotes padronizados de serviços recorrentes. 3) Em paralelo, estruturar a célula de inteligência macroeconômica e competitiva para monitorar Selic, câmbio, Plano Safra e movimentos de concorrentes, alimentando revisões trimestrais da estratégia. O ciclo de revisão deve ser trimestral, com gatilhos extraordinários para mudanças regulatórias relevantes, falhas de compliance e decisões judiciais que afetem o modelo de dados e serviços.", "criteria": ["ROI em 5 anos", "Risco de execução (técnico, comercial e organizacional)", "Grau de diferenciação / potencial de oceano azul"], "alternatives": ["Alternativa A – Expansão de serviços recorrentes (manutenção, retrofit e consultoria operacional)", "Alternativa B – Plataforma digital Baldan de dados, telemetria e serviços em modelo SaaS", "Alternativa C – Portfólio de soluções sustentáveis e pacotes de financiamento/retrofit verde"], "review_cycle": {"frequency": "Trimestral", "extraordinary_triggers": ["Mudança regulatória >10% custo", "Bloqueio de licenciamento", "Decisão judicial relevante", "Falha de compliance LGPD/setorial", "Entrada de competidor relevante", "Nova exigência de licenciamento que impeça a operação de serviços digitais ou de campo", "Decisão judicial que limite o uso de dados de telemetria ou modelos de assinatura no setor"]}, "score_comparison": "+18% acima da segunda opção", "monitoring_metrics": ["Participação de serviços e dados na receita total (%)", "Receita recorrente mensal (MRR) da plataforma digital e contratos de serviço", "Margem bruta média dos serviços versus produtos de ferro", "Taxa de adoção da plataforma (número de máquinas/implementos conectados)", "Churn de contratos de serviços e assinaturas (%)", "NPS de clientes de serviços e soluções digitais", "Payback médio dos pacotes de serviços e retrofit para o cliente (anos)"], "recommended_option": "Alternativa B – Plataforma digital Baldan de dados, telemetria e serviços em modelo SaaS", "final_recommendation": "A melhor opção é a Alternativa B, usando a Baldan Digital como eixo de um ecossistema de dados, serviços e sustentabilidade, com serviços recorrentes (Alternativa A) e inteligência macro/competitiva (Alternativa C) suportando a execução e redução de risco.", "priority_recommendations": [{"title": "Lançar plataforma Baldan Digital (dados, telemetria e serviços recorrentes)", "budget": "R$2-4M (desenvolvimento, integrações, time digital e go-to-market)", "priority": 1, "timeline": "9-18 meses (MVP em 9-12 meses)", "description": "Desenhar e lançar uma plataforma digital que conecte implementos Baldan (e, gradualmente, de terceiros) para monitoramento de uso, recomendação agronômica, manutenção preditiva e oferta de serviços em modelo de assinatura, criando receita recorrente pouco sensível a juros de 14,90% a.a.", "legal_feasibility": {"risk_level": "Médio", "mitigation_plan": "Contratar parecer jurídico especializado em LGPD e contratos de software antes do lançamento; adotar privacy by design (minimização de dados, anonimização quando possível, gestão de consentimento granular); estruturar termos de uso e SLAs com limites claros de responsabilidade e cobertura de seguros; se o risco se mostrar alto em determinadas funcionalidades (por ex., recomendações agronômicas automatizadas), iniciar com versão de analytics descritivo e relatórios de performance, escalando gradualmente para recomendações prescritivas após validação técnica e jurídica.", "requires_legal_opinion": true, "regulatory_dependencies": ["Adequação plena à LGPD (dados de clientes e telemetria)", "Contratos de licenciamento de software e termos de uso da plataforma", "Cláusulas de responsabilidade civil e SLA de serviços digitais"], "requires_statutory_change": false}}, {"title": "Escalar serviços recorrentes de manutenção, retrofit e consultoria operacional", "budget": "R$1-2M (desenho de ofertas, treinamento de rede e sistemas de gestão de contratos)", "priority": 2, "timeline": "6-12 meses", "description": "Criar portfólio estruturado de contratos de manutenção programada, retrofit de implementos para melhor eficiência e consultoria operacional em manejo de solo, reduzindo risco financeiro do cliente com ofertas modulares e pacotes de serviço de longo prazo.", "legal_feasibility": {"risk_level": "Médio", "mitigation_plan": "Obter parecer jurídico sobre modelos de contrato de serviço, responsabilidade por falhas de manutenção e limites de garantia; padronizar contratos com cláusulas claras de escopo, exclusões e limites de indenização; treinar equipes e rede de revendas em conformidade contratual e em normas de segurança; como alternativa de menor risco, iniciar com pacotes de manutenção preventiva em equipamentos já cobertos por garantia e só depois expandir para retrofits complexos e consultoria operacional aprofundada.", "requires_legal_opinion": true, "regulatory_dependencies": ["Revisão de contratos de prestação de serviços e garantias", "Adequação a normas de segurança do trabalho em campo", "Seguro de responsabilidade civil profissional (se aplicável)"], "requires_statutory_change": false}}, {"title": "Criar célula de inteligência macroeconômica e competitiva para orientar o oceano azul", "budget": "R$300-600k (time enxuto, ferramentas de dados e apoio de consultoria pontual)", "priority": 3, "timeline": "3-6 meses", "description": "Estruturar uma pequena célula interna (ou parceria) para monitorar juros (14,90% a.a.), câmbio (R$ 5,36/USD), Plano Safra, concorrentes e demandas por sustentabilidade, alimentando decisões sobre preços, mix de serviços, exportação e priorização de features digitais.", "legal_feasibility": {"risk_level": "Baixo", "requires_legal_opinion": false, "requires_statutory_change": false}}]}'::jsonb, 'completed', NULL, 374906, true, false, true, 'BWNOYEES', '2025-12-05 13:47:27.16356+00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-05 13:39:46.674198+00'::timestamptz, '2025-12-05 13:48:45.34421+00'::timestamptz, '2025-12-05 13:46:01.314907+00'::timestamptz, NULL)
