VALUES ('ddc894f6-c076-43ab-9bbc-83630881374d', NULL, NULL, NULL, '{"summary": "Nicho Brasil‑Peru é promissor se Câmara acelerar captação digital, liderança em dados e visibilidade de cases, mitigando juros altos e concorrência.", "threats": [{"source": "análise de mercado", "content": "Juros altos e queda no comércio reduzem demanda por missões e eventos", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Concorrência de câmaras bilaterais, Apex e consultorias especializadas", "confidence": "Média"}, {"source": "análise de mercado", "content": "Poder de barganha dos associados pressiona preços de associação", "confidence": "Média"}, {"source": "análise de mercado", "content": "Aceleração do networking digital global reduz relevância de eventos locais", "confidence": "Média"}], "strengths": [{"source": "fato", "content": "Alavancar legitimidade institucional em campanhas de captação", "confidence": "Alta"}, {"source": "fato", "content": "Explorar foco exclusivo no corredor Brasil‑Peru para nichos setoriais", "confidence": "Alta"}, {"source": "estimativa", "content": "Estruturar rede B2B/B2G para conectar empresas, bancos e governos", "confidence": "Média"}, {"source": "estimativa", "content": "Aprimorar modelo de associação para ampliar receita recorrente", "confidence": "Média"}], "weaknesses": [{"source": "estimativa", "content": "Ausência de máquina estruturada de aquisição e onboarding de associados", "confidence": "Média"}, {"source": "fato", "content": "Pouca divulgação atual de cases de sucesso no comércio bilateral", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Capacidades digitais, de dados e IA ainda pouco sistematizadas", "confidence": "Média"}, {"source": "estimativa", "content": "Dependência elevada de patrocínios e eventos pontuais de receita", "confidence": "Baixa"}], "opportunities": [{"source": "análise de mercado", "content": "Lançar plataformas digitais de matchmaking setorial Brasil‑Peru", "confidence": "Média"}, {"source": "análise de mercado", "content": "Oferecer hub de orientação prática em normas ALADI e regras do BCB", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Desenvolver observatório de dados Brasil‑Peru com IA para insights", "confidence": "Média"}, {"source": "análise de mercado", "content": "Organizar missões comerciais aproveitando PIB e câmbio favoráveis", "confidence": "Média"}]}'::jsonb, '{"legal": ["Acordos ALADI/Mercosul regulam tarifas Brasil-Peru, gerando demanda por apoio jurídico especializado", "Normas cambiais do BCB ligadas ao câmbio R$ 5,36/USD impactam contratos e meios de pagamento", "Índices IBGE (IPCA 0,09%, INPC 0,03%) orientam cláusulas de reajuste em contratos de serviços"], "social": ["Empresas B2B/B2G valorizam confiança institucional, favorecendo Câmara frente a consultorias", "Falta de cases Brasil-Peru reduz prova social; divulgá-los pode destravar adesão de novos membros", "Adoção de networking híbrido muda hábitos; Câmara deve adaptar formatos para engajar executivos"], "summary": "Juros altos e comércio em queda, mas PIB e câmbio favoráveis. Câmara deve explorar nichos Brasil-Peru, acelerar digital e apoiar em normas ALADI/BCB para crescer associados.", "economic": ["Comércio -0,30% e indústria -0,40% indicam demanda fraca, exigindo nichos Brasil-Peru resilientes", "Câmbio a R$ 5,36/USD torna Brasil mais competitivo, mas encarece serviços precificados em dólar", "PIB 12m 3,20% e desemprego 5,60% sugerem espaço moderado para ampliar base pagante de associados"], "political": ["Integração ALADI/Mercosul favorece novos acordos Brasil-Peru, exigindo atuação ativa da Câmara", "Política monetária restritiva (SELIC 14,90%) limita verbas públicas para comércio exterior", "Inflação 0,09% reduz pressão social, abrindo espaço político para integração Brasil-Peru"], "environmental": ["Custo da construção 0,27% limita reformas sustentáveis em espaços físicos usados pela Câmara", "IPP -0,25% reduz custo de bens, abrindo brecha para logística mais eficiente e ambientalmente cuidadosa", "Serviços 0,60% pode estimular demandas por certificações verdes em cadeias atendidas pela Câmara"], "technological": ["Digitalização aduaneira exige conteúdo técnico atualizado para orientar empresas Brasil-Peru", "Networking híbrido requer plataforma estável para conexões frequentes entre associados", "Maturidade digital 5 indica risco de ficar atrás de câmaras que investem em CRM e automação"]}'::jsonb, '{"summary": "O nicho Brasil‑Peru é moderadamente atrativo: rivalidade gerenciável, mas forte poder dos associados e de substitutos. Parcerias estratégicas e liderança em IA/dados serão decisivas para escalar base e gerar cases de alto impacto.", "buyer_power": "Poder do associado é alto: juros de 14,90% a.a., comércio -0,30% e desemprego 5,60% elevam pressão por preço e ROI, exigindo propostas claras de geração de leads e redução de risco comercial.", "supplier_power": "Poder médio de fornecedores: dependência de poucos hubs institucionais e serviços especializados, com custos de serviços +0,60% e construção +0,27%, pressiona margens em eventos e projetos bilaterais.", "disruption_ai_data": "IA/dados trazem disrupção alta: algoritmos podem automatizar prospecção, due diligence e matchmaking Brasil‑Peru; se a câmara não liderar em analytics, plataformas globais capturam o relacionamento com as empresas.", "threat_substitutes": "Substitutos fortes: plataformas B2B, programas públicos e consultorias reduzem dependência da câmara; digitalização aduaneira e serviços +0,60% favorecem soluções self‑service, exigindo proposta de valor exclusiva.", "competitive_rivalry": "Rivalidade média: nicho Brasil‑Peru limita players, mas câmaras e Apex disputam o mesmo orçamento B2B em cenário de PIB 12m 3,20% e serviços +0,60%, exigindo diferenciação em entrega de negócios.", "threat_new_entrants": "Ameaça média: relacionamento governamental e confiança institucional elevam barreiras, mas acordos ALADI/Mercosul e PIB 2,20% atraem novas câmaras, consultorias e plataformas digitais ao corredor Brasil‑Peru.", "buyer_power_intensity": "Alta", "overall_attractiveness": "Média", "strategic_implications": ["Lançar plataforma digital de matchmaking Brasil‑Peru com métricas claras (negócios gerados, tíquete médio) para justificar ROI e apoiar aquisição e retenção de associados.", "Estruturar alianças formais com governos, Apex, bancos e grandes operadores logísticos para oferecer programas conjuntos exclusivos e reduzir o poder de barganha de fornecedores-chave.", "Criar planos de associação escalonados e resultados‑baseados, adequados a juros de 14,90% e comércio -0,30%, combinando fees menores upfront com bônus atrelados a negócios fechados.", "Investir em marketing de conteúdo e PR binacional, divulgando cases com números (exportações, empregos, payback) para aumentar visibilidade, fortalecer reputação e acelerar conversão de leads em associados."], "supplier_power_intensity": "Média", "disruption_ai_data_intensity": "Alta", "threat_substitutes_intensity": "Alta", "competitive_rivalry_intensity": "Média", "power_partnerships_ecosystems": "Parcerias têm poder alto: alianças com governos, Apex, bancos e plataformas digitais, ancoradas em PIB 3,20% e câmbio R$ 5,36/USD, podem escalar alcance e engajamento e criar pacotes difíceis de replicar.", "threat_new_entrants_intensity": "Média", "power_partnerships_ecosystems_intensity": "Alta"}'::jsonb, '{"summary": "Em 90 dias, a Câmara estrutura funil digital, base jurídica e pilotos setoriais, preparando validação e escala do hub de dados e cases Brasil–Peru.", "plan_90_days": [{"focus": "Fundação", "month": "Mês 1", "objective": "Desenhar funil digital Brasil–Peru e governança jurídica de dados e cases", "investment": "R$ 15-25 mil", "key_results": ["Definir 3 personas-alvo e 3 ofertas de entrada Brasil–Peru aprovadas", "Selecionar 1 CRM e ativar ambiente piloto com até 5 usuários internos", "Aprovar 2 minutas-padrão: LGPD/termos de uso 