INSERT INTO analyses (id, submission_id, enrichment_id, company_id, swot, pestel, porter, okrs, synthesis, tam_sam_som, benchmarking, blue_ocean, growth_hacking, scenarios, bsc, decision_matrix, status, error_message, processing_time_ms, is_visible_to_user, is_blurred, is_public, access_code, access_code_created_at, pdf_url, pdf_generated_at, approved_at, approved_by, sent_at, sent_to, created_at, updated_at, completed_at, deleted_at)
VALUES ('7b89124f-2196-4311-bc13-ac11f00da0e6', NULL, NULL, NULL, '{"summary": "IBREI tem missão clara e nicho relevante, mas precisa escalar associados e digitalizar prospecção para aproveitar janela macro e se diferenciar em mercado competitivo.", "threats": [{"source": "análise de mercado", "content": "Responder a alto poder de compradores com propostas de valor modulares", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Diferenciar oferta frente a câmaras, associações e consultorias rivais", "confidence": "Média"}, {"source": "estimativa", "content": "Competir com redes digitais gratuitas criando comunidade própria forte", "confidence": "Média"}, {"source": "análise de mercado", "content": "Mitigar impacto de juros 14,90% em projetos com modelos de baixo CAPEX", "confidence": "Alta"}], "strengths": [{"source": "fato", "content": "Alavancar missão ponte público-privada em campanhas de atração", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Usar nicho em relações internacionais para posicionamento premium", "confidence": "Média"}, {"source": "análise de mercado", "content": "Transformar eventos em hubs de networking estruturado B2B/B2G", "confidence": "Média"}, {"source": "estimativa", "content": "Otimizar site para captação de leads e onboarding digital de membros", "confidence": "Média"}], "weaknesses": [{"source": "fato", "content": "Criar máquina comercial focada em crescimento de associados", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Mapear e divulgar claramente benefícios por segmento de associado", "confidence": "Média"}, {"source": "estimativa", "content": "Estruturar CRM e funil de relacionamento com empresas e instituições", "confidence": "Média"}, {"source": "estimativa", "content": "Tornar públicos dados básicos de porte, governança e resultados", "confidence": "Média"}], "opportunities": [{"source": "análise de mercado", "content": "Criar produtos para nichos que crescem com PIB 3,20% e inflação 0,09%", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Oferecer programas de internacionalização mitigando câmbio R$5,36/USD", "confidence": "Alta"}, {"source": "estimativa", "content": "Usar IA para prospecção, qualificação e matching entre membros", "confidence": "Média"}, {"source": "análise de mercado", "content": "Firmar acordos com órgãos públicos e entidades globais para coeventos", "confidence": "Média"}]}'::jsonb, '{"legal": ["SELIC 14.90% a.a. exige cláusulas contratuais aderentes a cenário de juros altos e voláteis", "Câmbio R$ 5.36/USD demanda contratos com hedge cambial em projetos apoiados pelo IBREI", "Inflação 0.09% (12 meses) reduz litígios sobre reajustes, mas exige transparência contratual"], "social": ["Desemprego 5.60 % limita renda, mas aumenta procura por redes que abrem portas no exterior", "Inflação 0.09% (12 meses) reduz resistência social a reajustes graduais de anuidades", "Serviços 0.60 % sugere cautela de empresas com gastos em eventos e memberships premium"], "summary": "Juros 14.90% a.a. e câmbio R$ 5.36/USD limitam expansão, mas PIB 3.20 % e inflação 0.09% (12 meses) criam janela para o IBREI crescer em nichos de internacionalização e networking público-privado.", "economic": ["SELIC 14.90% a.a. eleva custo de capital para expansão e adesão de novos associados", "Câmbio R$ 5.36/USD favorece exportadores, mas encarece viagens e projetos internacionais", "PIB 2.20 % e comércio -0.30 % indicam recuperação setorial desigual para associados"], "political": ["PIB 3.20 % em 12 meses aumenta foco oficial em diplomacia econômica e acordos comerciais", "Desemprego 5.60 % pressiona governo por programas pró-negócios e internacionalização", "Serviços 0.60 % pode orientar políticas de apoio a serviços intensivos em comércio exterior"], "environmental": ["Custo de construção 0.27 % abre espaço para sedes mais eficientes e sustentáveis em energia", "Indústria -0.40 % reforça pauta ESG em cadeias globais que IBREI pode articular", "IPP -0.25 % sugere janela para adquirir equipamentos verdes a custos ligeiramente menores"], "technological": ["Serviços 0.60 % pressiona digitalização de eventos IBREI para ganhar escala com menor custo", "Maturidade digital média exige investir em plataforma online de comunidade e conteúdos", "Custo de construção 0.27 % permite avaliar hubs físicos, integrados a soluções digitais"]}'::jsonb, '{"summary": "Atratividade setorial média: alto poder de compradores e substitutos pressiona crescimento de associados, mas parcerias estratégicas e uso intensivo de IA criam espaço para diferenciação e expansão internacional escalável do IBREI.", "buyer_power": "Poder de associados alto; com Selic a 14,90% e PIB 12m em 3,20%, empresas priorizam iniciativas com ROI claro, pressionando preços de membership e exigindo entregas mensuráveis.", "supplier_power": "Poder de fornecedores médio; especialistas e venues qualificados são escassos, mas desemprego de 5,60% e serviços crescendo só 0,60% contêm custos e ampliam alternativas de talento.", "disruption_ai_data": "Disrupção por IA alta; curadoria de conteúdo, matchmaking e análise de mercados podem ser automatizados, exigindo ofertas de inteligência proprietária e uso avançado de dados dos associados.", "threat_substitutes": "Substitutos altos: câmaras de comércio, APEX, consultorias e comunidades digitais oferecem networking similar, com baixo custo marginal em um setor de serviços que cresce 0,60%.", "competitive_rivalry": "Rivalidade média; mercado de relações internacionais é fragmentado, mas múltiplas associações disputam os mesmos decisores, exigindo oferta de networking público‑privado altamente qualificada.", "threat_new_entrants": "Ameaça de novos entrantes média; barreiras baseadas em reputação e rede institucional reduzem entrada rápida, porém custos fixos baixos e ambiente digital facilitam novos hubs de networking especializado.", "buyer_power_intensity": "Alta", "overall_attractiveness": "Média", "strategic_implications": ["Desenvolver proposta de valor mensurável para membros (KPIs de negócios gerados) para reduzir poder de barganha de compradores.", "Criar programa estruturado de alianças com APEX, câmaras e universidades para ampliar capilaridade internacional do IBREI.", "Lançar plataforma digital própria com IA para matchmaking de negócios e conteúdo personalizado, elevando barreiras à entrada.", "Mapear e engajar sistematicamente executivos‑referência como embaixadores do IBREI, reduzindo dependência de poucos fornecedores‑chave."], "supplier_power_intensity": "Média", "disruption_ai_data_intensity": "Alta", "threat_substitutes_intensity": "Alta", "competitive_rivalry_intensity": "Média", "power_partnerships_ecosystems": "Parcerias têm poder alto; cocriação com APEX, câmaras e universidades alavanca credibilidade e escala global, capturando o ciclo de PIB 3,20% e câmbio a R$ 5,36/USD pró‑exportações.", "threat_new_entrants_intensity": "Média", "power_partnerships_ecosystems_intensity": "Alta"}'::jsonb, '{"summary": "Em 90 dias, IBREI estrutura plataforma, CRM, parcerias-piloto e primeiros hubs para evoluir a hub digital de dealmaking internacional.", "plan_90_days": [{"focus": "Fundação", "month": "Mês 1", "objective": "Estruturar bases digitais, comerciais e de governança para o hub de dealmaking", "investment": "R$ 15-25 mil", "key_results": ["Mapear benefícios por segmento e jornada do associado em documento aprovado", "Selecionar fornecedor da plataforma e fechar contrato inicial", "Implantar CRM simples com campos padrão e 100% da base atual cadastrada"], "aligned_recommendation": "Implantar plataforma digital integrada de relacionamento, conteúdo e captação de associados"}, {"focus": "Crescimento", "month": "Mês 2", "objective": "Desenhar MVP da plataforma e formalizar programa de parcerias institucionais", "investment": "R$ 20-40 mil", "key_results": ["Concluir desenho do MVP da área do associado com fluxo básico", "Publicar regulamento do programa de parcerias e matriz de benefícios", "Configurar integrações iniciais entre site, CRM e ferramenta de e-mail"], "aligned_recommendation": "Estruturar programa de parcerias institucionais nacionais e internacionais com foco em captação e retenção de associados"}, {"focus": "Consolidação", "month": "Mês 3", "objective": "Lançar piloto controlado da plataforma com parcerias e hubs/comitês iniciais", "investment": "R$ 25-45 mil", "key_results": ["Lançar beta da plataforma com 30-50 usuários internos e associados-piloto", "Assinar ao menos 3 MoUs ou acordos de parceria com instituições-chave", "Instalar 1 hub regional e 1 comitê temático com líderes nomeados"], "aligned_recommendation": "Lançar rede piloto de hubs regionais e comitês temáticos para engajamento de associados"}], "success_metrics": ["MVP da plataforma definido e beta lançado com grupo piloto de associados", "CRM e funil de relacionamento ativos com base atual 100% cadastrada", "Programa de parcerias e 1 hub + 1 comitê operando em regime piloto"], "execution_phases": {"scale": {"focus": "Expansão controlada", "duration": "Meses 7-12", "objectives": ["Escalar plataforma, parcerias e hubs validados para mais regiões e segmentos", "Consolidar o IBREI como hub digital de negócios internacionais baseado em resultados"], "key_results": ["Alcançar 3-5 hubs regionais e 3-5 comitês temáticos ativos", "Aumentar associados ativos em 30-50% em relação ao pré-projeto"], "prerequisites": ["Validação bem-sucedida da plataforma e dos modelos de parceria", "Métricas mínimas de engajamento e satisfação atingidas nos pilotos"], "investment_range": "R$ 130-200 mil"}, "foundation": {"focus": "Estruturação", "duration": "Meses 1-3", "objectives": ["Definir arquitetura do hub digital de dealmaking e governança de dados", "Organizar máquina comercial básica, CRM e regras de hubs/comitês"], "key_results": ["Fornecedor da plataforma escolhido e contrato assinado até o mês 3", "CRM implantado e 100% dos associados atuais cadastrados"], "investment_range": "R$ 60-110 mil", "capacity_requirements": {"team": "4-6 pessoas", "dependencies": ["Contratação de fornecedor de plataforma e ferramentas (CRM, e-mail)", "Parecer jurídico sobre LGPD, termos de uso e modelos de parceria"], "skills_needed": ["Gestão de produto digital", "Tecnologia/integrações web", "Jurídico (LGPD, contratos, MoUs)", "Comercial/parcerias institucionais", "Gestão de comunidades/hubs"]}}, "validation": {"focus": "Pilotos", "duration": "Meses 4-6", "objectives": ["Validar proposta de valor do hub digital com grupo piloto de associados", "Testar programa de parcerias e hubs em poucos casos controlados"], "key_results": ["Executar piloto da plataforma com 50-100 usuários ativos", "Firmar 5-8 parcerias que gerem leads qualificados para o IBREI"], "prerequisites": ["Fase 1 concluída com plataforma beta funcional", "Regulamentos de parcerias e hubs/comitês aprovados"], "investment_range": "R$ 80-140 mil"}}, "total_investment": "R$ 60-110 mil", "capacity_assessment": {"blockers": ["Capacidade limitada da equipe para tocar projeto digital e parcerias em paralelo", "Possível resistência interna à migração de eventos presenciais para hub digital"], "team_readiness": "Média", "budget_adequacy": "Limitado", "stakeholder_alignment": "Parcial"}}'::jsonb, '{"roadmap": ["Curto Prazo (3-6 meses): Desenvolver MVP da plataforma digital, implementar CRM, definir planos de membership e captar primeiros 50 associados digitais", "Médio Prazo (6-12 meses): Escalar para 200+ associados, ativar 2 hubs internacionais piloto, integrar métricas de impacto e selo de credibilidade", "Longo Prazo (12+ meses): Consolidar presença em 5+ mercados, automatizar dealmaking com IA avançada, atingir autossustentabilidade financeira"], "key_findings": ["Migrar para hub digital de dealmaking é essencial para eliminar dependência do presencial e escalar com custo marginal baixo", "Parcerias com entidades públicas e câmaras de comércio criam barreiras de entrada e legitimam proposta de valor", "Segmentação de planos (básico, premium, enterprise) maximiza LTV e permite upsell estruturado"], "main_findings": ["Força: Missão clara de fomento a negócios internacionais e foco em networking público-privado de alto nível", "Fraqueza: Ausência de infraestrutura digital robusta e dependência excessiva de eventos presenciais para captação", "Oportunidade: Janela macro favorável para nichos de internacionalização com demanda crescente por conexões qualificadas", "Ameaça: Alto poder de substitutos e compradores pressiona diferenciação; juros de 14,90% a.a. limitam investimentos"], "important_notes": ["Câmbio R$ 5,36/USD impacta diretamente custos de expansão internacional e precificação de serviços", "Modelo de receita atual não está claro; validar sustentabilidade financeira antes de escalar", "Ausência de dados públicos (CNPJ, porte) pode dificultar parcerias institucionais formais"], "central_challenge": "Escalar base de associados e consolidar presença internacional em ambiente de juros elevados e câmbio volátil, migrando de networking tradicional para hub digital de dealmaking global.", "executive_summary": "O IBREI possui missão clara e nicho relevante em relações empresariais internacionais, mas enfrenta pressão competitiva e necessidade urgente de digitalização. A janela macroeconômica (PIB 3,20%, inflação controlada) favorece nichos de internacionalização. Priorizar plataforma digital com IA, CRM robusto e parcerias institucionais estratégicas permitirá diferenciar-se de substitutos genéricos e escalar aquisição de associados com modelo de receita recorrente.", "strategic_priorities": ["Lançar plataforma digital MVP com curadoria ativa e matching por IA em 90 dias", "Estruturar CRM e funil de aquisição segmentado por perfil de associado", "Firmar 3-5 parcerias-piloto com instituições âncora para validar modelo"], "consistency_validation": {"flags": ["Receita atual e projetada não estão quantificadas; impossível validar viabilidade financeira dos OKRs", "Tamanho da equipe desconhecido; capacidade de execução do roadmap é incerta", "Recomenda-se validar CNPJ e estrutura jurídica antes de formalizar parcerias institucionais"], "legal_alignment": true, "capacity_alignment": false, "financial_alignment": false, "overall_realism_score": 6}, "overall_recommendation": "Priorizar digitalização acelerada com MVP em 90 dias, validar modelo de receita recorrente com parcerias-piloto e escalar de forma conservadora dado ambiente de juros elevados."}'::jsonb, '{"sam": "R$ 60M - 120M", "som": "R$ 2.5M - 9M", "tam": "R$ 200M - 350M", "cagr": "+5% a.a. (baseado em: serviços 0,60%, PIB 12m 3,20% e ajuste RACE/AIM)", "summary": "Mercado brasileiro de associações em relações empresariais internacionais é nichado (TAM ~R$ 200M-350M), com espaço realista para o IBREI capturar R$ 3.5M-7M/ano.", "assumptions": ["Brasil tem 30-50k empresas/profissionais ativos em comércio exterior (benchmark)", "Ticket médio de associação estimado em R$ 3k-6k/ano por membro (dados setoriais)", "Faixa de R$ 2-10M/ano por associação com base em benchmarks de entidades brasileiras"], "som_scenarios": {"realistic": {"probability": 50, "value_range": "R$ 3.5M - 7M", "market_share": "8-12% do SAM"}, "optimistic": {"probability": 20, "value_range": "R$ 6M - 9M", "market_share": "15-20% do SAM"}, "conservative": {"probability": 30, "value_range": "R$ 2M - 4M", "market_share": "3-6% do SAM"}}, "tam_scenarios": {"realistic": {"probability": 50, "value_range": "R$ 230M - 300M"}, "optimistic": {"probability": 20, "value_range": "R$ 280M - 350M"}, "conservative": {"probability": 30, "value_range": "R$ 200M - 250M"}}, "caveat_message": "⚠️ Estimativas baseadas em benchmarks gerais de associações e proxies de membros potenciais, não em dados específicos do nicho.", "confidence_level": 45, "calculation_notes": "TAM/SAM via potencial de membros em comércio exterior; SOM pela captura de 3-15% do SAM em 3 cenários usando modelo RACE/AIM.", "data_sources_used": {"direct_data": ["Desafio e público-alvo informados pelo IBREI (formulário do cliente)"], "proxy_calculations": ["Estimativa de empresas/profissionais em internacionalização x anuidade média por membro", "Projeção de alcance RACE/AIM: Reach total, Activate nicho comércio exterior, Monetize associados"], "benchmark_extrapolations": ["Faixa de receita anual típica de associações setoriais no Brasil (R$ 2M - 10M)", "Indicadores macroeconômicos: serviços 0,60%, PIB 12m 3,20%, câmbio R$ 5.36/USD", "Taxa Selic 14.90% a.a. como limitador de expansão rápida de patrocínios"]}, "estimation_method": "benchmark_setorial", "baseline_recommendation": "conservative"}'::jsonb, '{"summary": "Num mercado nichado de R$ 200M–350M, o IBREI tem espaço para crescer membership e receitas a R$ 3,5M–7M/ano.", "best_practices": ["Posicionamento nítido como ponte entre setor público e privado em negócios internacionais.", "Atuação nichada em relações empresariais internacionais, alinhada ao mercado de R$ 200M–350M.", "Potencial de capturar R$ 3,5M–7M/ano ao escalar base de associados e parcerias estratégicas."], "performance_gaps": ["Aquisição de novos associados menos estruturada que câmaras de comércio binacionais consolidadas.", "Oferta e benefícios de membership pouco claros no site, reduzindo conversão de visitantes em membros.", "Presença internacional menos institucionalizada que entidades com escritórios e chapters em vários países."], "competitors_analyzed": ["Câmara de Comércio Brasil-Estados Unidos (Amcham Brasil)", "Associação Brasileira de Comércio Exterior (AEB)"]}'::jsonb, '{"raise": ["Curadoria ativa de conexões B2B, B2G e PPP com foco em negócios fechados", "Transparência em métricas de impacto: deals, empregos e investimentos gerados", "Uso intensivo de IA para inteligência de mercados e monitoramento regulatório"], "create": ["Plataforma digital de matchmaking global com IA e métricas de sucesso em tempo real", "Programas de Deal Rooms setoriais e por país conectando público e privado", "Selo IBREI de credibilidade internacional baseado em performance comprovada"], "reduce": ["Dependência de eventos presenciais como principal canal de relacionamento", "Comunicação institucional formalista e pouco orientada a resultados", "Ofertas padronizadas de cursos e missões iguais às de câmaras e associações"], "summary": "O IBREI migra de uma lógica de eventos e networking genérico para um hub digital de dealmaking global, combinando IA, curadoria ativa e métricas de impacto. Ao eliminar burocracia e ofertas comoditizadas, reduzir a dependência do presencial e elevar transparência e personalização, o instituto cria uma proposta única: conectar, validar e acelerar negócios internacionais com um selo de credibilidade baseado em resultados concretos para profissionais, empresas e instituições públicas e privadas.", "eliminate": ["Eventos genéricos sem metas claras de negócios ou internacionalização", "Burocracia de filiação e renovação que desestimula novos associados", "Conteúdos excessivamente acadêmicos sem aplicação prática imediata"], "new_value_curve": "Do modelo centrado em eventos para um hub digital de dealmaking global, com IA, métricas de impacto e pontes público-privadas escaláveis."}'::jsonb, '{"summary": "Usar programas de internacionalização e IA para escalar aquisição de associados, estruturar planos segmentados e upsell para maximizar LTV.", "leap_loop": {"name": "LEAP Loop", "type": "acquisition", "steps": ["Land: Captar leads com trilhas de internacionalização e coeventos com órgãos públicos e câmaras estrangeiras", "Engage: Nutrir com webinars, diagnósticos de internacionalização e conteúdo segmentado por perfil de associado", "Activate: Oferecer teste de associação com onboarding guiado e proposta personalizada por segmento de membro", "Propagate: Programa de indicações entre membros com bônus em eventos, visibilidade institucional e crédito em anuidades"], "metrics": ["CAC", "Taxa de Conversão", "Coeficiente Viral"], "bottleneck": "Ausência de máquina comercial e CRM estruturado para captar, qualificar e converter novos associados em escala"}, "scale_loop": {"name": "SCALE Loop", "type": "monetization", "steps": ["Satisfy: Entregar benefícios claros por segmento com programas de internacionalização, matchmaking e acesso a coeventos", "Convert: Estruturar planos de associação e trilhas pagas por nicho, com proposta baseada no valor de negócios gerados", "Loop Back: Criar calendário contínuo de eventos e projetos com renovações facilitadas e gestão ativa de relacionamento", "Expand: Oferecer upgrades para planos corporativos, patrocínios, missões internacionais e consultorias especializadas"], "metrics": ["LTV", "Taxa de Recompra", "Receita de Expansão"], "bottleneck": "Benefícios pouco mapeados por segmento e baixa transparência de resultados, limitando precificação, renovação e upsell"}}'::jsonb, '{"realist": {"name": "Cenário Realista", "description": "Economia cresce moderadamente (PIB 2,2–3,2%), serviços 0,60% e comércio -0,30%. SELIC fica em 14,90% e câmbio em R$ 5,36/USD, com custo de capital alto, mas ganhos para exportadores. Inflação em 0,09% (12m) preserva poder de compra dos serviços do IBREI, que cresce de forma gradual, focado em nichos de internacionalização e networking público-privado.", "probability": 60, "required_actions": ["Priorizar setores que se beneficiam do câmbio em R$ 5,36/USD (exportadores, serviços globais), oferecendo programas de membership dedicados.", "Desenvolver produtos de baixo custo (webinars, certificações online) para ampliar base de associados sem elevar muito o ticket.", "Intensificar parcerias com instituições públicas para programas cofinanciados de capacitação e missões técnicas seletivas.", "Mapear polos regionais no Brasil com maior dinamismo em serviços (0,60%) e criar células locais de relacionamento IBREI."]}, "summary": "O IBREI opera em ambiente de juros elevados (14,90% a.a.), câmbio de R$ 5,36/USD e PIB em torno de 3,20%, que cria nichos, mas limita expansão ampla. Preparar-se exige portfólio flexível, digitalização e parcerias institucionais. Monitorar juros, câmbio e atividade em serviços permitirá ajustar rapidamente ritmo de expansão, retenção e captação de associados.", "optimistic": {"name": "Cenário Otimista", "description": "Com PIB em 3,2% e serviços acima de 1%, SELIC recua de 14,90% para perto de 9% e inflação segue em 0,09% (12m). Câmbio aprecia de R$ 5,36 para ~R$ 4,80/USD, estimulando acordos e investimentos. IBREI torna-se hub de internacionalização e networking público-privado, acelerando entrada de associados e expansão para América Latina e Europa.", "probability": 20, "required_actions": ["Lançar campanha agressiva de novos associados com planos segmentados para empresas exportadoras e prestadores de serviços internacionais.", "Firmar convênios com agências de promoção de exportações e embaixadas para programas bilaterais de missões e rodadas de negócios.", "Criar hubs temáticos (digital e presenciais) por região-alvo, com trilhas de capacitação em internacionalização e diplomacia corporativa."]}, "pessimistic": {"name": "Cenário Pessimista", "description": "Choques externos elevam SELIC de 14,90% para acima de 17% e câmbio salta de R$ 5,36 para além de R$ 6,00/USD. PIB recua para perto de 0%, indústria (-0,40%) e comércio (-0,30%) aprofundam queda e desemprego sobe além de 8%. Orçamentos de internacionalização são cortados; IBREI enfrenta estagnação de associados e menor apoio público-privado.", "probability": 20, "required_actions": ["Focar retenção: planos mais flexíveis, benefícios tangíveis de curto prazo e comunidade digital exclusiva para associados atuais.", "Substituir eventos presenciais caros por plataformas online de matchmaking e inteligência de mercado internacional.", "Diversificar receitas com cursos pagos, projetos sob demanda para órgãos públicos e consultorias pontuais em ambiente regulatório."]}, "mitigation_tactics": ["Desenvolver um portfólio modular de serviços (gratuitos, básicos e premium) que possa ser rapidamente ajustado ao ciclo econômico.", "Construir reservas financeiras e um pipeline contínuo de editais, patrocínios e convênios para reduzir dependência apenas de anuidades.", "Firmar alianças estratégicas com câmaras de comércio, universidades e organismos multilaterais para manter fluxo de projetos anticíclicos.", "Investir em infraestrutura digital própria (plataforma de comunidade e conteúdo) para reduzir custo marginal de atendimento por associado."], "early_warning_signals": ["Trajetória da SELIC e comunicações do Banco Central: alta acima de 14,90% ou corte acelerado abaixo de 12% mudam radicalmente apetite por internacionalização.", "Movimentos bruscos do câmbio frente aos atuais R$ 5,36/USD, especialmente rompimentos persistentes acima de R$ 6,00 ou abaixo de R$ 5,00.", "Revisões do PIB (2,20–3,20%), serviços (0,60%), indústria (-0,40%) e desemprego (5,60%): quedas simultâneas indicam retração de orçamento dos associados."]}'::jsonb, '{"summary": "BSC foca em expansão de associados via hub digital global, com IA e impacto mensurável", "customer": ["Elevar nº de associados ativos e satisfeitos no Brasil e exterior", "Aumentar taxa de sucesso em deals conectados pelo hub IBREI"], "financial": ["Elevar receita recorrente via planos de associação e serviços digitais", "Aumentar % de receita internacional no faturamento total"], "learning_growth": ["Desenvolver competências em IA, curadoria e análise de dados", "Fortalecer rede global de parceiros institucionais estratégicos"], "internal_processes": ["Digitalizar fluxo de matchmaking e validação de oportunidades", "Implementar métricas de impacto por deal e por programa"]}'::jsonb, '{"score": "8.4/10", "summary": "A análise multicriterial indica que a Alternativa A – crescimento digital orientado a membership e conteúdo premium – oferece maior impacto na base de associados em 3 anos, com melhor relação custo-benefício em um contexto de juros elevados (SELIC 14,90% a.a.), câmbio em R$ 5,36/USD e PIB em 3,20%. A digitalização da jornada do associado permite escalar captação e retenção com menor dependência de estrutura física e de capital, além de criar um canal estruturado para conectar profissionais, empresas e instituições públicas e privadas no Brasil e no exterior. As Recomendações 1, 2 e 3 formam um roadmap integrado: (1) construir a infraestrutura digital e de dados (plataforma); (2) acoplar parcerias institucionais plugadas a essa plataforma, gerando fluxo recorrente de novos membros e projetos internacionais; e (3) fortalecer o engajamento regional e temático via hubs e comitês. O ciclo de revisão trimestral, com gatilhos extraordinários jurídicos e regulatórios, permitirá ajustar rapidamente a estratégia frente a mudanças de custo, licenças, decisões judiciais ou falhas de compliance. Próximos passos: validar internamente as prioridades, aprovar orçamento e cronograma, obter revisão jurídica dos documentos-chave (termos da plataforma e minutas de parceria) e iniciar o piloto digital com um conjunto limitado de segmentos e regiões, expandindo conforme métricas de adoção e sustentabilidade financeira.", "criteria": ["Impacto na base de associados em 3 anos", "Viabilidade financeira no cenário de juros SELIC a 14,90% a.a.", "Complexidade institucional e risco jurídico"], "alternatives": ["Alternativa A - Crescimento digital orientado a membership e conteúdo premium", "Alternativa B - Rede de hubs regionais e comitês temáticos presenciais", "Alternativa C - Crescimento via parcerias institucionais e projetos internacionais sob medida"], "review_cycle": {"frequency": "Trimestral", "extraordinary_triggers": ["Mudança regulatória >10% custo", "Bloqueio de licenciamento", "Decisão judicial relevante", "Falha de compliance LGPD/setorial", "Entrada de competidor relevante"]}, "score_comparison": "+18% acima da segunda opção", "monitoring_metrics": ["Número de novos associados por trimestre (total e por canal: digital, parcerias, hubs)", "Taxa de renovação de associados (%) e churn anual", "Receita recorrente de anuidades e patrocínios ligados à plataforma digital e parcerias", "Número de eventos e projetos internacionais realizados em cooperação com parceiros", "Índice de satisfação/NPS dos associados com serviços e conteúdo do IBREI", "Taxa de engajamento digital (acessos à plataforma, uso de conteúdos, participação em webinars)", "Tempo médio do ciclo de conversão de lead em associado"], "recommended_option": "Alternativa A - Crescimento digital orientado a membership e conteúdo premium", "final_recommendation": "A melhor opção é a Alternativa A, combinando plataforma digital de membership e conteúdo premium, pois maximiza escala de associados com baixo CAPEX, reduz risco institucional e permite integrar, de forma modular, parcerias e hubs regionais.", "priority_recommendations": [{"title": "Implantar plataforma digital integrada de relacionamento, conteúdo e captação de associados", "budget": "R$150-250k", "priority": 1, "timeline": "9-12 meses", "description": "Desenvolver e lançar uma plataforma digital própria do IBREI, conectada ao site atual, que concentre: cadastro e gestão de associados, área de membro com conteúdos exclusivos (webinars, reports, trilhas de internacionalização), agenda de eventos híbridos e matchmaking básico entre profissionais, empresas e instituições. Focar em ofertas de baixo custo de capital, com forte relevância internacional e em serviços, aproveitando o cenário de juros elevados (14,90% a.a.), câmbio em R$ 5,36/USD e PIB de 3,20% para posicionar o IBREI como hub digital de negócios internacionais.", "legal_feasibility": {"risk_level": "Baixo", "mitigation_plan": "Mapear fluxos de dados pessoais desde o desenho da plataforma; incluir cláusulas de confidencialidade e responsabilidade em contratos com fornecedores de TI; revisão jurídica dos termos de uso e da política de privacidade antes do go-live; manter log de consentimentos e opção clara de opt-out.", "requires_legal_opinion": false, "regulatory_dependencies": ["Adequação integral à LGPD na gestão de dados de associados e leads", "Contratos com provedores de tecnologia (SaaS, meios de pagamento)", "Termos de uso e política de privacidade para usuários da plataforma"], "requires_statutory_change": false}}, {"title": "Estruturar programa de parcerias institucionais nacionais e internacionais com foco em captação e retenção de associados", "budget": "R$80-120k", "priority": 2, "timeline": "6-9 meses", "description": "Criar um programa formal de parcerias com entidades empresariais, câmaras de comércio, universidades, órgãos públicos e organismos internacionais, para: (i) co-organizar eventos e missões internacionais; (ii) oferecer benefícios cruzados a associados (descontos, acesso a conteúdo, certificações); (iii) gerar fluxo recorrente de novos membros via acordos de indicação. Priorizar mercados onde o câmbio em R$ 5,36/USD favoreça a atração de players estrangeiros interessados em Brasil e empresas brasileiras voltadas à internacionalização.", "legal_feasibility": {"risk_level": "Médio", "mitigation_plan": "Submeter minutas-padrão de MoUs e contratos de parceria a parecer jurídico antes de qualquer assinatura; limitar obrigações financeiras e de resultado do IBREI nos contratos, evitando garantias excessivas; prever cláusulas claras de rescisão e de não exclusividade; em contextos mais sensíveis, iniciar cooperação via protocolos de intenções não vinculantes como alternativa de menor risco, evoluindo para contratos mais robustos após validação prática da parceria.", "requires_legal_opinion": true, "regulatory_dependencies": ["Análise contratual de Memorandos de Entendimento (MoUs) e acordos de cooperação", "Cláusulas de compliance e anticorrupção em parcerias com entes públicos", "Adequação a regras de patrocínio e uso de marca de parceiros"], "requires_statutory_change": false}}, {"title": "Lançar rede piloto de hubs regionais e comitês temáticos para engajamento de associados", "budget": "R$40-80k", "priority": 3, "timeline": "3-6 meses", "description": "Implementar, inicialmente em caráter piloto, hubs regionais (ex.: Sudeste, Sul, Nordeste) e comitês temáticos (ex.: comércio exterior, investimentos, ESG, tecnologia) coordenados por associados-líderes. Objetivos: aproximar o IBREI de empresas e profissionais em diferentes regiões, aumentar a frequência de interações, gerar inteligência de mercado e identificar oportunidades de projetos e parcerias. Estruturar os hubs como grupos de trabalho não autônomos juridicamente, alinhados ao estatuto atual, para evitar complexidade desnecessária.", "legal_feasibility": {"risk_level": "Médio", "mitigation_plan": "Criar regulamento interno claro definindo papel, limites de atuação e processo de nomeação dos líderes; deixar expresso que hubs e comitês não têm personalidade jurídica própria nem autonomia para assumir obrigações em nome do IBREI; em caso de dúvida quanto à aderência ao estatuto, manter o modelo como grupos de trabalho consultivos (alternativa de menor risco) até eventual revisão estatutária futura, se necessária.", "requires_legal_opinion": false, "regulatory_dependencies": ["Regulamento interno dos hubs e comitês alinhado ao estatuto vigente", "Política de representação institucional (quem pode falar em nome do IBREI)", "Regras de prevenção de conflitos de interesse entre líderes voluntários e o Instituto"], "requires_statutory_change": false}}]}'::jsonb, 'completed', NULL, 319458, true, false, true, 'HQ4D2MEA', '2025-12-05 11:12:44.189833+00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-05 11:06:07.228381+00'::timestamptz, '2025-12-05 11:14:36.711975+00'::timestamptz, '2025-12-05 11:11:26.414015+00'::timestamptz, NULL)
